    fun forLanguage(code: String?): AppDictionary {
        val normalized = code?.trim()?.lowercase() ?: "en"
        return when (normalized) {
            "hi" -> hi
            "gu" -> gu
            "mr" -> mr
            "pa" -> pa
            "bn" -> bn
            "ta" -> ta
            "te" -> te
            "kn" -> kn
            "ml" -> ml
            "or", "od" -> od
            "as" -> asLang
            "ur" -> ur
            "mai" -> mai
            "en" -> en
            else -> if (normalized.startsWith("hi")) hi else en
        }
    }
